    safety_llm = get_chat_safety_llm()
    qdrant = get_chat_qdrant_client()
    embedding_model = None

    try:
        from pipeline.llm_factory import get_embedding_model
        embedding_model = get_embedding_model()
    except Exception as exc:
        logger.warning("[!] Embedding model failed to initialize at startup: %s", exc)

    if safety_llm is None:
        logger.warning("[!] Chat safety LLM failed to initialize at startup")
    else:
        logger.info("[✓] Chat safety LLM initialized at startup")

    if qdrant is None:
        logger.warning("[!] Chat Qdrant client failed to initialize at startup")
    else:
        logger.info("[✓] Chat Qdrant client initialized at startup")

    if embedding_model is None:
        logger.warning("[!] Embedding model failed to initialize at startup")
    else:
        logger.info("[✓] Embedding model initialized at startup")

    return llm, safety_llm, qdrant, embedding_model

def get_chat_quota(user: AuthenticatedUser) -> dict[str, int]:
    limit = max(settings.chat_rate_limit, 0)
    key = _key_for(user)
    with _lock:
        used = _chat_counts.get(key, 0)
    return {
        "limit": limit,
        "used": used,
        "remaining": max(limit - used, 0),
    }

def _get_context(
    query: str,
    stage: str,
    vector_store: VectorStoreProvider,
    pageindex_provider: PageIndexProvider,
) -> str:
    mode = settings.retrieval_mode.strip().lower()

    if mode == "pageindex":
        if not pageindex_provider.is_loaded():
            raise HTTPException(status_code=500, detail="PageIndex data nahi load hua!")

        context = pageindex_provider.search(query)
        if not context:
            raise HTTPException(status_code=500, detail="PageIndex se context nahi mila!")
        return context

    if mode == "hybrid":
        from services.hybrid_retrieval import hybrid_context

        context = hybrid_context(
            query=query,
            stage=stage,
            vector_store=vector_store,
            pageindex_provider=pageindex_provider,
            top_k=settings.hybrid_top_k,
        )
        if not context:
            raise HTTPException(status_code=500, detail="Hybrid retrieval se context nahi mila!")
        return context

    # Default: RAG
    if not vector_store.is_loaded():
        raise HTTPException(status_code=500, detail="Knowledge base nahi load hua!")

    docs = vector_store.search(f"{query}\nSchedule and chemicals for {stage} maize")
    return "\n".join([d.page_content for d in docs])

