def _to_async_database_url(database_url: str) -> str:
    """Normalize PostgreSQL URLs for SQLAlchemy asyncpg usage."""
    if database_url.startswith("postgres://"):
        return "postgresql+asyncpg://" + database_url[len("postgres://"):]
    if database_url.startswith("postgresql://") and "+asyncpg" not in database_url:
        return "postgresql+asyncpg://" + database_url[len("postgresql://"):]
    return database_url

def _to_sync_database_url(database_url: str) -> str:
    """Normalize PostgreSQL URLs for psycopg2 usage."""
    return (
        database_url
        .replace("postgresql+asyncpg://", "postgresql://")
        .replace("postgresql+psycopg2://", "postgresql://")
    )

def async_database_url(self) -> str:
    """Database URL formatted for SQLAlchemy async engine creation."""
    return self._to_async_database_url(self.resolved_database_url)

def sync_database_url(self) -> str:
    """Database URL formatted for psycopg2 connections."""
    return self._to_sync_database_url(self.resolved_database_url)

def qdrant_client_kwargs(self) -> Dict[str, str]:
    """Return QdrantClient kwargs for server or local filesystem mode."""
    if self.qdrant_url:
        kwargs = {"url": self.qdrant_url}
        if self.qdrant_api_key:
            kwargs["api_key"] = self.qdrant_api_key
        return kwargs

    return {"path": self.qdrant_path}

def qdrant_location(self) -> str:
    """Human-readable Qdrant location for logs."""
    return self.qdrant_url or self.qdrant_path

def resolved_cors_origins(self) -> List[str]:
    """Return configured CORS origins as a clean list."""
    return [origin.strip() for origin in self.cors_origins.split(",") if origin.strip()]

def resolved_qdrant_collections(self) -> List[str]:
    """Return de-duplicated collection names to query in Qdrant."""
    names: List[str] = []

    if self.qdrant_collection_name.strip():
        names.append(self.qdrant_collection_name.strip())

    for name in self.qdrant_collection_names.split(","):
        cleaned = name.strip()
        if cleaned:
            names.append(cleaned)

    # Preserve order while removing duplicates
    return list(dict.fromkeys(names))

async def init(self, auto_create_tables: bool = True) -> None:
    """Initialize engine + pool only once for the app lifecycle."""
    if self._initialized:
        return

    async with self._init_lock:
        if self._initialized:
            return

        database_url = settings.async_database_url

        engine_kwargs = {
            "echo": settings.database_echo,
            "pool_pre_ping": settings.database_pool_pre_ping,
        }

        if not database_url.startswith("sqlite"):
            engine_kwargs.update(
                {
                    "pool_size": settings.database_pool_size,
                    "max_overflow": settings.database_max_overflow,
                    "pool_timeout": settings.database_pool_timeout,
                    "pool_recycle": settings.database_pool_recycle,
                }
            )

        self.engine = create_async_engine(database_url, **engine_kwargs)
        self.session_factory = async_sessionmaker(
            bind=self.engine,
            class_=AsyncSession,
            expire_on_commit=False,
            autoflush=False,
            autocommit=False,
        )

        if auto_create_tables:
            await self.create_all_tables()

        self._initialized = True

async def lifespan(_app):
    """Run startup/shutdown lifecycle hooks."""
    print("\n" + "="*50)
    print("    KISAN MITRA - STARTING UP")
    print("="*50)

    mode = settings.retrieval_mode.strip().lower()
    print(f"[*] Retrieval mode: {mode}")

    await db_manager.init(auto_create_tables=settings.database_auto_create_tables)
    print("[✓] PostgreSQL engine initialized with async pool")

    # Initialise agent DB tables (user_profiles, conversation_states)
    try:
        import pipeline.database as agent_db
        agent_db.init_db()
    except Exception as _e:
        print(f"[!] Agent DB init warning: {_e}")

    if mode == "pageindex":
        pageindex_provider = get_pageindex_provider()
        if pageindex_provider.is_loaded():
            print("[✓] PageIndex loaded successfully!")
        else:
            print("[!] WARNING: PageIndex failed to load!")
    elif mode == "hybrid":
        vector_store = get_vector_store()
        pageindex_provider = get_pageindex_provider()
        try:
            from services.bm25 import get_bm25_retriever
            bm25_loaded = get_bm25_retriever().is_loaded()
        except Exception as exc:
            bm25_loaded = False
            print(f"[!] WARNING: BM25 markdown index failed to initialize: {exc}")

        print(f"[*] Hybrid source status: rag={vector_store.is_loaded()} bm25={bm25_loaded} pageindex={pageindex_provider.is_loaded()}")

        _llm, _safety_llm, chat_qdrant, _embedding_model = init_chat_resources_on_startup()
        if chat_qdrant is not None:
            print("[✓] Chat Qdrant client initialized.")
        else:
            print("[!] WARNING: Chat Qdrant client failed to initialize.")
        if _embedding_model is not None:
            print("[✓] Embedding model initialized.")
        else:
            print("[!] WARNING: Embedding model failed to initialize.")
    else:
        # Default: RAG (Qdrant)
        vector_store = get_vector_store()
        if vector_store.is_loaded():
            collections = ", ".join(settings.resolved_qdrant_collections)
            print(f"[✓] Qdrant Knowledge Base loaded (checked collections: {collections})")
        else:
            print("[!] WARNING: Qdrant knowledge base not loaded. Run scripts/ingest.py or scripts/ingestion_docling.py first.")

        # Initialize chat agent resources at startup so tool calls never run with None client
        _llm, _safety_llm, chat_qdrant, _embedding_model = init_chat_resources_on_startup()
        if chat_qdrant is not None:
            print("[✓] Chat Qdrant client initialized.")
        else:
            print("[!] WARNING: Chat Qdrant client failed to initialize.")
        if _embedding_model is not None:
            print("[✓] Embedding model initialized.")
        else:
            print("[!] WARNING: Embedding model failed to initialize.")

    print("="*50 + "\n")
    yield

    await db_manager.dispose()
    print("[✓] PostgreSQL engine disposed")

def _clear_pending_requirement(state: AgentState) -> None:
    state["pending_user_intent"] = None
    state["pending_requirement"] = None
    state["pending_context"] = {}

def _run_prechecks(state: AgentState, tool_calls: List[Dict[str, Any]], loop_count: int, llm, qdrant_client=None) -> bool:
    """Run deterministic checks before the main LLM call. Returns True if the node should exit early."""
    if state.get("resume_pending_intent"):
        return False

    if state.get("user_sowing_date") and not state.get("user_crop_stage"):
        _update_crop_stage_from_sowing_date(
            state,
            state["user_sowing_date"],
            tool_calls,
            loop_count,
            qdrant_client=qdrant_client,
        )

    if is_sowing_date_query(state.get("raw_input", "")):
        profile = state.get("user_profile") or {}
        sowing_date = state.get("user_sowing_date") or profile.get("sowing_date")
        state["needs_more_info"] = False
        if sowing_date:
            state["final_response"] = f"आपकी मक्का की बुवाई की तारीख {sowing_date} है।"
        else:
            state["final_response"] = (
                "मेरे पास अभी आपकी मक्का की बुवाई की तारीख नहीं है। "
                "कृपया बुवाई की तारीख बताइए, जैसे `2026-03-06` या `20 दिन पहले`."
            )
        return True

    sowing_reply = is_sowing_date_reply(state.get("raw_input", ""), state)
    extracted_sowing_date = extract_sowing_date_from_text(state.get("raw_input", ""))
    if extracted_sowing_date:
        apply_sowing_date_to_state(state, extracted_sowing_date)
        _update_crop_stage_from_sowing_date(state, extracted_sowing_date, tool_calls, loop_count, qdrant_client=qdrant_client)
        if sowing_reply:
            resume_payload = _build_resume_payload(
                state,
                resolved_fact_ack=f"ठीक है, मैंने आपकी मक्का की बुवाई की तारीख {extracted_sowing_date} सेव कर ली है।",
                context_patch={
                    "user_sowing_date": extracted_sowing_date,
                    "user_crop_stage": state.get("user_crop_stage"),
                },
            )
            if resume_payload:
                _apply_resume_payload(state, resume_payload)
                return False
            state["needs_more_info"] = False
            state["final_response"] = f"ठीक है, मैंने आपकी मक्का की बुवाई की तारीख {extracted_sowing_date} सेव कर ली है।"
            return True
        else:
            state["needs_more_info"] = False
            state["final_response"] = f"ठीक है, मैंने आपकी मक्का की बुवाई की तारीख {extracted_sowing_date} सेव कर ली है।"
            return True
    elif should_interpret_relative_sowing_date(state.get("raw_input", ""), state):
        print(
            "[SowingDate] Attempting relative sowing date resolution: "
            f"input={state.get('raw_input', '')!r} | conversation_id={state.get('conversation_id')} | "
            f"user_id={state.get('user_id')}"
        )
        relative_sowing_date, needs_datetime_for_sowing = resolve_relative_sowing_date(
            state.get("raw_input", ""),
            tool_calls,
        )
        if relative_sowing_date:
            apply_sowing_date_to_state(state, relative_sowing_date)
            _update_crop_stage_from_sowing_date(state, relative_sowing_date, tool_calls, loop_count, qdrant_client=qdrant_client)
            resume_payload = _build_resume_payload(
                state,
                resolved_fact_ack=f"ठीक है, मैंने आपकी मक्का की बुवाई की तारीख {relative_sowing_date} सेव कर ली है।",
                context_patch={
                    "user_sowing_date": relative_sowing_date,
                    "user_crop_stage": state.get("user_crop_stage"),
                },
            )
            if resume_payload:
                _apply_resume_payload(state, resume_payload)
                return False
            else:
                state["needs_more_info"] = False
                state["final_response"] = f"ठीक है, मैंने आपकी मक्का की बुवाई की तारीख {relative_sowing_date} सेव कर ली है।"
                return True
        elif needs_datetime_for_sowing and auto_call_datetime_tool(
            state,
            tool_calls,
            loop_count,
            qdrant_client=qdrant_client,
            call_suffix="sowing",
        ):
            return True

    if sowing_reply:
        if auto_call_datetime_tool(
            state,
            tool_calls,
            loop_count,
            qdrant_client=qdrant_client,
            call_suffix="sowing_fallback",
        ):
            return True

        llm_resolved_sowing_date = _resolve_sowing_date_with_llm(llm, state, tool_calls)
        if llm_resolved_sowing_date:
            apply_sowing_date_to_state(state, llm_resolved_sowing_date)
            _update_crop_stage_from_sowing_date(state, llm_resolved_sowing_date, tool_calls, loop_count, qdrant_client=qdrant_client)
            resume_payload = _build_resume_payload(
                state,
                resolved_fact_ack=f"ठीक है, मैंने आपकी मक्का की बुवाई की तारीख {llm_resolved_sowing_date} सेव कर ली है।",
                context_patch={
                    "user_sowing_date": llm_resolved_sowing_date,
                    "user_crop_stage": state.get("user_crop_stage"),
                },
            )
            if resume_payload:
                _apply_resume_payload(state, resume_payload)
                return False
            else:
                state["needs_more_info"] = False
                state["final_response"] = f"ठीक है, मैंने आपकी मक्का की बुवाई की तारीख {llm_resolved_sowing_date} सेव कर ली है।"
                return True

        state["needs_more_info"] = False
        state["final_response"] = (
            "कृपया बुवाई की तारीख थोड़ी और साफ़ तरीके से बताइए, जैसे `2026-03-06`, "
            "`20 दिन पहले`, या `पिछले महीने 5 तारीख`."
        )
        return True

    if needs_maize_sowing_date(state.get("raw_input", ""), state):
        _set_pending_requirement(
            state,
            original_query=state.get("raw_input", ""),
            requirement=MAIZE_SOWING_DATE_REQUIREMENT,
            pending_context={"crop": "maize"},
        )
        state["needs_more_info"] = False
        state["final_response"] = (
            "मक्का की सही और स्टेज-आधारित सलाह देने के लिए पहले बुवाई की तारीख बताइए। "
            "कृपया तारीख `YYYY-MM-DD` में बताएं, जैसे `2025-07-10`."
        )
        return True

    # Only auto-route to FAQ while crop stage is still unknown. Once crop stage
    # is known, let the normal LLM/tool flow decide whether to call RAG or FAQ.
    if (not state.get("user_crop_stage")) and should_route_to_maize_faq(state.get("raw_input", ""), state):
        if _auto_call_maize_faq_tool(
            state,
            tool_calls,
            loop_count,
            qdrant_client=qdrant_client,
        ):
            return True
    else:
        print(f"[FAQ Router] No FAQ route matched for query: {state.get('raw_input', '')}")

    if needs_datetime_tool(state.get("raw_input", "")) and auto_call_datetime_tool(
        state,
        tool_calls,
        loop_count,
        qdrant_client=qdrant_client,
        call_suffix="general",
    ):
        return True

    return False

def agent_node(state: AgentState, llm, qdrant_client=None) -> AgentState:
    """
    Main decision-making node.
    1. Translates Studio Chat UI `messages` → `raw_input` seamlessly.
    2. Runs deterministic prechecks.
    3. Builds context + prompts LLM.
    4. Handles tool calling vs final response.
    """
    tool_calls: List[Dict[str, Any]] = list(state.get("tool_calls") or [])
    loop_count: int = state.get("loop_count", 0)

    if loop_count >= MAX_LOOPS:
        state["needs_more_info"] = False
        state["final_response"] = (
            state.get("final_response")
            or "I've gathered information but reached the processing limit. Please refine your question."
        )
        return state

    if state.get("messages") and not state.get("raw_input"):
        last_msg = state["messages"][-1]
        if last_msg.type == "human":
            state["raw_input"] = last_msg.content

    print(f"\n[Agent Node] Processing input: {state.get('raw_input')}")

    if _run_prechecks(state, tool_calls, loop_count, llm, qdrant_client=qdrant_client):
        return state

    messages = build_messages(state)

    try:
        if state.get("tools_used", False):
            response = llm.invoke(messages)
            studio_msgs = list(state.get("messages", []))
            studio_msgs.append(AIMessage(content=response.content or ""))
            state["messages"] = studio_msgs
        else:
            llm_with_tools = llm.bind_tools(
                [
                    {
                        "type": "function",
                        "function": {
                            "name": t.get("name"),
                            "description": t.get("description"),
                            "parameters": t.get("parameters", {}),
                        },
                    }
                    for t in TOOLS
                ]
            )
            response = llm_with_tools.invoke(messages)

            studio_msgs = list(state.get("messages", []))
            if response.content:
                studio_msgs.append(AIMessage(content=response.content))
            state["messages"] = studio_msgs

    except Exception as exc:
        error_text = str(exc)
        log_llm_call(
            conversation_id=state.get("conversation_id"),
            user_id=state.get("user_id"),
            source="agent.error",
            request={"messages_count": len(messages), "loop_count": loop_count},
            error=error_text,
        )
        state["needs_more_info"] = False
        if "invalid_api_key" in error_text or "Incorrect API key" in error_text or "401" in error_text:
            state["final_response"] = (
                "OpenAI API key गलत या inactive लग रही है। कृपया backend की `.env` में "
                "`OPENAI_API_KEY` सही करके server restart करें।"
            )
        else:
            state["final_response"] = "Sorry, I encountered an error. Please try again."
        return state

    log_llm_call(
        conversation_id=state.get("conversation_id"),
        user_id=state.get("user_id"),
        source="agent.invoke",
        request={
            "messages_count": len(messages),
            "loop_count": loop_count,
            "tools_mode": not state.get("tools_used", False),
        },
        response={
            "has_content": bool(getattr(response, "content", "")),
            "tool_calls_count": len((getattr(response, "tool_calls", None) or [])),
        },
    )

    raw_tool_calls = getattr(response, "tool_calls", None) or []
    if not raw_tool_calls:
        raw_tool_calls = response.additional_kwargs.get("tool_calls") or []

    if raw_tool_calls:
        for tc in raw_tool_calls:
            if isinstance(tc, dict):
                name = tc.get("name") or tc.get("function", {}).get("name", "")
                args_raw = tc.get("args") or tc.get("function", {}).get("arguments", "{}")
                call_id = tc.get("id", f"call_{name}_{loop_count}")
            else:
                name = tc.name
                args_raw = tc.args
                call_id = getattr(tc, "id", f"call_{name}_{loop_count}")

            if isinstance(args_raw, str):
                try:
                    params = json.loads(args_raw)
                except json.JSONDecodeError:
                    params = {}
            else:
                params = dict(args_raw)

            if name == "web_search":
                params.setdefault("state", state.get("user_state") or "Uttar Pradesh")
                params.setdefault("country", state.get("user_country") or "India")
            elif name == "rag_search":
                if any((tc.get("tool") == "rag_search") for tc in tool_calls):
                    print("[RAG Router] Skipping duplicate rag_search requested by model because rag_search already ran in this turn.")
                    continue
                _maybe_call_faq_before_rag(
                    state,
                    tool_calls,
                    loop_count,
                    qdrant_client=qdrant_client,
                )
                if state.get("user_crop_stage"):
                    params.setdefault("crop_stage", state.get("user_crop_stage"))
            elif name == "set_crop_stage" and state.get("user_sowing_date"):
                params.setdefault("sowing_date", state.get("user_sowing_date"))
            elif name in {"rag_search", "faq_search_by_crop_stage"}:
                if state.get("user_crop_stage"):
                    params.setdefault("crop_stage", state.get("user_crop_stage"))

            result = dispatch_tool(
                name,
                params,
                qdrant_client=qdrant_client,
                chat_history=state.get("chat_history"),
                conversation_id=state.get("conversation_id"),
                user_id=state.get("user_id"),
                call_id=call_id,
            )

            tool_calls.append({"id": call_id, "tool": name, "params": params, "result": result})

            if name == "rag_search" and "chunks" in result:
                existing = list(state.get("retrieved_chunks") or [])
                existing.extend(result["chunks"])
                state["retrieved_chunks"] = existing
            elif name == "faq_search_by_crop_stage":
                _ensure_rag_after_faq(
                    state,
                    tool_calls,
                    loop_count,
                    qdrant_client=qdrant_client,
                )
            elif name == "geocode_location" and "error" not in result:
                state["user_location"] = result.get("location") or result.get("resolved_address") or params.get("address")
                state["user_state"] = result.get("state") or state.get("user_state")
                state["user_country"] = result.get("country") or state.get("user_country")
                state["user_latitude"] = result.get("latitude")
                state["user_longitude"] = result.get("longitude")
            elif name == "set_crop_stage" and "error" not in result:
                resolved_sowing_date = result.get("sowing_date") or params.get("sowing_date")
                if resolved_sowing_date:
                    apply_sowing_date_to_state(state, resolved_sowing_date)
                _apply_crop_stage_to_state(state, result)

        state["tool_calls"] = tool_calls
        state["loop_count"] = loop_count + 1
        state["needs_more_info"] = True
        return state

    state["tool_calls"] = tool_calls
    state["loop_count"] = loop_count + 1
    state["needs_more_info"] = False
    state["final_response"] = response.content or ""
    state["resume_pending_intent"] = False
    state["resume_acknowledgment"] = None
    return state

def profile_block(profile: dict | None) -> str:
    """Build a human-readable profile context string to append to the system prompt."""
    if not profile:
        return ""

    lines = ["\n--- Known User Profile ---"]
    if profile.get("name"):
        lines.append(f"Name: {profile['name']}")
    if profile.get("language"):
        lines.append(f"Preferred language: {profile['language']}")
    if profile.get("location"):
        lines.append(f"Location: {profile['location']}")
    if profile.get("state"):
        lines.append(f"State: {profile['state']}")
    if profile.get("country"):
        lines.append(f"Country: {profile['country']}")
    if profile.get("sowing_date"):
        lines.append(f"Maize sowing date: {profile['sowing_date']}")
    if profile.get("crop_stage"):
        lines.append(f"Current maize crop stage: {profile['crop_stage']}")
    if profile.get("latitude") is not None and profile.get("longitude") is not None:
        lines.append(f"Coordinates: {profile['latitude']}, {profile['longitude']}")
    if profile.get("farm_size_acres"):
        lines.append(f"Farm size: {profile['farm_size_acres']} acres")
    if profile.get("soil_type"):
        lines.append(f"Soil type: {profile['soil_type']}")
    if profile.get("crops"):
        lines.append(f"Crops: {', '.join(profile['crops'])}")

    extra = profile.get("extra_facts") or {}
    for key, value in extra.items():
        lines.append(f"{key}: {value}")

    lines.append("Use this profile to personalize your responses without asking again.")
    lines.append("--- End of Profile ---")
    return "\n".join(lines)

def build_messages(state: AgentState) -> list:
    """Construct the full message list for the LLM call."""
    profile_ctx = profile_block(state.get("user_profile"))
    messages = [SystemMessage(content=SYSTEM_PROMPT + profile_ctx)]

    summary = state.get("conversation_summary")
    if summary:
        messages.append(
            SystemMessage(
                content=f"[Earlier conversation summary — treat as established context]\n{summary}"
            )
        )

    if state.get("resume_pending_intent"):
        ack = state.get("resume_acknowledgment") or ""
        messages.append(
            SystemMessage(
                content=(
                    "The user has just provided a missing detail for an earlier unanswered request. "
                    f"Briefly acknowledge it using this exact fact if natural: {ack} "
                    "Then answer the original user question directly in the same response. "
                    "Do not ask again for the same missing detail."
                )
            )
        )

    tool_calls = state.get("tool_calls") or []
    tool_names = [call.get("tool") for call in tool_calls]
    if "faq_search_by_crop_stage" in tool_names and "rag_search" in tool_names:
        messages.append(
            SystemMessage(
                content=(
                    "When both faq_search_by_crop_stage and rag_search results are available, "
                    "present the FAQ guidance FIRST as the primary answer. "
                    "Then add supporting or supplementary points from the broader RAG/manual results. "
                    "Do not ignore the FAQ answer and do not reverse this order."
                )
            )
        )

    history = state.get("chat_history") or []
    if history:
        messages.append(
            SystemMessage(
                content=(
                    "IMPORTANT: The conversation history below is ordered oldest→newest. "
                    "More recent messages carry HIGHER priority. When information conflicts, "
                    "always prefer the most recent statement."
                )
            )
        )

    pairs: list[tuple] = []
    i = 0
    while i < len(history):
        user_msg = history[i] if i < len(history) else None
        asst_msg = history[i + 1] if i + 1 < len(history) else None
        pairs.append((user_msg, asst_msg))
        i += 2

    total_turns = len(pairs)
    for turn_idx, (user_msg, asst_msg) in enumerate(pairs, start=1):
        age = total_turns - turn_idx
        if age == 0:
            label = f"[Turn {turn_idx}/{total_turns} — MOST RECENT ↑ highest priority]"
        elif age <= 1:
            label = f"[Turn {turn_idx}/{total_turns} — recent]"
        else:
            label = f"[Turn {turn_idx}/{total_turns} — older, lower priority]"

        if user_msg:
            messages.append(HumanMessage(content=f"{label}\n{user_msg.get('content', '')}"))
        if asst_msg:
            messages.append(AIMessage(content=f"{label}\n{asst_msg.get('content', '')}"))

    messages.append(HumanMessage(content=state.get("raw_input", "")))

    for call in tool_calls:
        tool_name = call.get("tool")
        params = call.get("params", {})
        result = call.get("result", {})
        call_id = call.get("id", f"call_{tool_name}")

        messages.append(
            AIMessage(
                content="",
                tool_calls=[{"name": tool_name, "args": params, "id": call_id}],
            )
        )
        messages.append(ToolMessage(content=json.dumps(result), tool_call_id=call_id))

    return messages

def _contains_any(text: str, keywords: list[str]) -> bool:
    lowered = (text or "").lower()
    return any(keyword in lowered for keyword in keywords)

def _last_assistant_asked_sowing_date(state: AgentState) -> bool:
    history = state.get("chat_history") or []
    for message in reversed(history):
        if message.get("role") != "assistant":
            continue
        content = (message.get("content") or "").lower()
        return any(
            hint in content
            for hint in [
                "sowing date",
                "planting date",
                "बुवाई की तारीख",
                "बोवाई की तारीख",
                "बुवाई",
                "बोवाई",
            ]
        )
    return False

def _asked_for_requirement(message_content: str, requirement: str | None) -> bool:
    content = (message_content or "").lower()
    if requirement == MAIZE_SOWING_DATE_REQUIREMENT:
        return any(
            hint in content
            for hint in [
                "sowing date",
                "planting date",
                "बुवाई की तारीख",
                "बोवाई की तारीख",
                "बुवाई",
                "बोवाई",
            ]
        )
    return False

def get_pending_user_intent(state: AgentState) -> str | None:
    """Return the pending user intent, reconstructing it from history if needed."""
    pending_query = (state.get("pending_user_intent") or "").strip()
    if pending_query:
        return pending_query

    history = state.get("chat_history") or []
    if len(history) < 2:
        return None

    requirement = state.get("pending_requirement") or MAIZE_SOWING_DATE_REQUIREMENT
    last_assistant_idx = None
    for idx in range(len(history) - 1, -1, -1):
        message = history[idx]
        if message.get("role") != "assistant":
            continue
        if _asked_for_requirement(message.get("content") or "", requirement):
            last_assistant_idx = idx
            break

    if last_assistant_idx is None:
        return None

    for idx in range(last_assistant_idx - 1, -1, -1):
        message = history[idx]
        if message.get("role") != "user":
            continue
        content = (message.get("content") or "").strip()
        if not content:
            continue
        if requirement == MAIZE_SOWING_DATE_REQUIREMENT:
            if _is_maize_stage_critical_query(content):
                return content
            if not is_sowing_date_query(content):
                return content

    return None

def needs_datetime_tool(user_text: str) -> bool:
    text = (user_text or "").strip().lower()
    return bool(text) and any(keyword in text for keyword in TEMPORAL_KEYWORDS)

def extract_sowing_date_from_text(user_text: str) -> str | None:
    text = (user_text or "").strip()
    if not text:
        return None

    iso_match = re.search(r"\b(\d{4})[-/](\d{2})[-/](\d{2})\b", text)
    if iso_match:
        year, month, day = iso_match.groups()
        return f"{year}-{month}-{day}"

    dmy_match = re.search(r"\b(\d{2})[-/](\d{2})[-/](\d{4})\b", text)
    if dmy_match:
        day, month, year = dmy_match.groups()
        return f"{year}-{month}-{day}"

    return None

def _extract_relative_sowing_days(user_text: str) -> int | None:
    text = (user_text or "").strip().lower()
    if not text:
        return None

    patterns = [
        r"\b(\d{1,3})\s*(day|days)\s*ago\b",
        r"\b(\d{1,3})\s*(din)\s*(pehle|pahle|phle|phale)\b",
        r"\b(\d{1,3})\s*(दिन)\s*(पहले)\b",
    ]
    for pattern in patterns:
        match = re.search(pattern, text)
        if match:
            return int(match.group(1))
    return None

def get_latest_datetime_tool_result(tool_calls: list[dict[str, Any]]) -> dict[str, Any] | None:
    for tool_call in reversed(tool_calls):
        if tool_call.get("tool") == "get_current_datetime":
            result = tool_call.get("result") or {}
            if isinstance(result, dict) and result.get("date"):
                return result
    return None

def needs_maize_sowing_date(user_text: str, state: AgentState) -> bool:
    text = (user_text or "").strip()
    profile = state.get("user_profile") or {}
    if not text:
        return False
    if not _contains_any(text, MAIZE_KEYWORDS):
        return False
    if is_sowing_date_query(text):
        return False
    if not (
        _is_maize_stage_critical_query(text)
        or _contains_any(text, MAIZE_FAQ_KEYWORDS)
        or _contains_any(text, MAIZE_ADVICE_KEYWORDS)
    ):
        return False
    if state.get("user_sowing_date") or profile.get("sowing_date"):
        return False
    if state.get("user_crop_stage") or profile.get("crop_stage"):
        return False
    return True

def should_route_to_stage_faq(user_text: str, state: AgentState) -> bool:
    """
    Deterministically route maize stage-specific advisory questions to the FAQ tool
    when the crop stage is already known.
    """
    text = (user_text or "").strip()
    if not text:
        return False
    if not state.get("user_crop_stage"):
        return False
    if is_sowing_date_query(text):
        return False
    return _is_maize_stage_critical_query(text)

def should_route_to_maize_faq(user_text: str, state: AgentState) -> bool:
    """
    Route maize FAQ-like questions to FAQ retrieval even when crop stage is unknown.
    This covers general maize questions like soil, seed, sowing, climate, etc.
    """
    text = (user_text or "").strip()
    if not text:
        return False
    if not _contains_any(text, MAIZE_KEYWORDS):
        return False
    if is_sowing_date_query(text):
        return False
    if state.get("user_crop_stage"):
        return should_route_to_stage_faq(text, state) or _contains_any(text, MAIZE_FAQ_KEYWORDS)
    return _contains_any(text, MAIZE_FAQ_KEYWORDS)

def should_interpret_relative_sowing_date(user_text: str, state: AgentState) -> bool:
    """Only treat relative phrases like '20 din pehle' as sowing-date input in sowing-date context."""
    if _extract_relative_sowing_days(user_text) is None:
        return False

    text = (user_text or "").strip()
    if _contains_any(text, SOWING_DATE_QUERY_KEYWORDS):
        return True

    return _last_assistant_asked_sowing_date(state)

def is_sowing_date_query(user_text: str) -> bool:
    text = (user_text or "").strip()
    if not text:
        return False
    return _contains_any(text, MAIZE_KEYWORDS) and _contains_any(text, SOWING_DATE_QUERY_KEYWORDS)

def is_sowing_date_reply(user_text: str, state: AgentState) -> bool:
    """True when the user is likely replying to the assistant's request for sowing date."""
    text = (user_text or "").strip()
    if not text:
        return False
    if extract_sowing_date_from_text(text):
        return True
    if _extract_relative_sowing_days(text) is not None and _last_assistant_asked_sowing_date(state):
        return True
    return False

def get_db_connection():
    """Context manager to safely checkout and release a database connection."""
    if not pg_pool:
        raise RuntimeError("Database connection pool is not initialized.")

    conn = pg_pool.getconn()
    try:
        yield conn
    finally:
        # Always return the connection to the pool
        pg_pool.putconn(conn)

def delete_state(conversation_id: str) -> None:
    """Remove a conversation state record."""
    if not conversation_id:
        return

    try:
        with get_db_cursor() as cur:
            cur.execute(
                "DELETE FROM conversation_states WHERE conversation_id = %s;",
                (conversation_id,)
            )
    except Exception as e:
        print(f"[DB] delete_state failed for {conversation_id}: {e}")

def _should_loop(state: AgentState) -> str:
    if state.get("needs_more_info", False):
        return "agent"
    return END

def _sanitize_profile_patch(
    *,
    user_msg: str,
    patch: dict,
    resolved_sowing_date: str | None = None,
) -> dict:
    """Keep profile extraction from inventing or overwriting canonical dates."""
    sanitized = dict(patch or {})

    extracted_sowing_date = sanitized.get("sowing_date")
    explicit_user_sowing_date = extract_sowing_date_from_text(user_msg)

    if resolved_sowing_date:
        if extracted_sowing_date and extracted_sowing_date != resolved_sowing_date:
            print(
                "[Profile] Overriding extracted sowing_date "
                f"{extracted_sowing_date} with resolved state value {resolved_sowing_date}"
            )
        sanitized["sowing_date"] = resolved_sowing_date
    elif extracted_sowing_date and not explicit_user_sowing_date:
        print(
            "[Profile] Dropping extracted sowing_date because user message did not "
            "contain an explicit absolute date."
        )
        sanitized.pop("sowing_date", None)
    elif explicit_user_sowing_date:
        sanitized["sowing_date"] = explicit_user_sowing_date

    return sanitized

