def _is_symbol_heavy(text: str) -> bool:
    if not text:
        return False
    meaningful = sum(ch.isalnum() or ch.isspace() for ch in text)
    return meaningful / max(len(text), 1) < 0.4

def _has_supported_query_terms(text: str) -> bool:
    lowered = (text or "").lower()
    return any(term in lowered for term in _SUPPORTED_QUERY_TERMS)

def _is_low_information_query(text: str) -> tuple[str, str] | None:
    stripped = text.strip()
    if not stripped:
        return "block", "empty_query"

    lowered = stripped.lower()
    words = re.findall(r"[a-zA-Z]+|[\u0900-\u097F]+", lowered)
    digits = re.findall(r"\d", lowered)

    if len(stripped) <= 3:
        return "block", "too_short"

    if re.fullmatch(r"[\W_]+", stripped):
        return "block", "symbols_only"

    if _is_symbol_heavy(stripped) and len(words) <= 1:
        return "block", "symbol_noise"

    if digits and not words and len(digits) >= 4:
        return "block", "numeric_noise"

    if words and all(word in _ABUSE_WORDS for word in words) and len(words) <= 6:
        return "block", "abuse_only"

    if _has_supported_query_terms(stripped):
        return None

    if words:
        long_words = [w for w in words if len(w) >= 4]
        unique_ratio = len(set(words)) / max(len(words), 1)
        joined_words = "".join(words)
        vowelish = sum(ch in "aeiou" for ch in joined_words)
        if _has_devanagari(joined_words):
            vowelish += sum(ch in _DEVANAGARI_VOWELS for ch in joined_words)
        if len(long_words) >= 2 and unique_ratio > 0.8 and vowelish <= 2:
            return "block", "gibberish_query"

    if re.search(r"\bselect\b", lowered) and ("from" in lowered or "ffrom" in lowered) and len(words) <= 4:
        return "block", "sql_like_noise"

    return None

def _heuristic_safety_check(user_text: str) -> tuple[str, str] | None:
    text = (user_text or "").strip()
    if settings.chat_security_blocking_enabled:
        for pattern, reason in _HEURISTIC_SAFETY_PATTERNS:
            if pattern.search(text):
                return "block", reason

    if settings.chat_low_info_blocking_enabled:
        low_info = _is_low_information_query(text)
        if low_info:
            return low_info

    return None

def execute_get_current_datetime(timezone_offset_hours: float = 5.5) -> Dict[str, Any]:
    """Return current date/time in the given timezone (default IST)."""
    try:
        tz = timezone(timedelta(hours=timezone_offset_hours))
        now = datetime.now(tz)
        month = now.month
        # Simple agricultural season mapper for India
        if month in (2, 3, 4, 5):
            season = "Zaid / Spring (Zaid Maize season)"
        elif month in (6, 7, 8, 9, 10):
            season = "Kharif (Monsoon season)"
        else:
            season = "Rabi (Winter season)"
        return {
            "date":         now.strftime("%Y-%m-%d"),
            "day_of_week":  now.strftime("%A"),
            "time":         now.strftime("%H:%M:%S"),
            "timezone":     f"UTC{'+' if timezone_offset_hours >= 0 else ''}{timezone_offset_hours}",
            "farming_season": season,
            "datetime_iso": now.isoformat(),
        }
    except Exception as e:
        return {"error": str(e)}

def _json_safe(value: Any) -> Any:
    """Best-effort conversion to JSON-serialisable types."""
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    if isinstance(value, dict):
        return {str(k): _json_safe(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_json_safe(v) for v in value]
    if isinstance(value, tuple):
        return [_json_safe(v) for v in value]
    return str(value)

def _normalize_question(text: str) -> str:
    cleaned = re.sub(r"[^a-z0-9\s]+", " ", (text or "").lower())
    return " ".join(cleaned.split())

def _load_maize_tree() -> Dict[str, Any]:
    with open(settings.maize_faq_tree_path, "r", encoding="utf-8") as f:
        return json.load(f)

def _parse_stage_label(stage_label: str) -> Tuple[int, int | None]:
    digits = [int(num) for num in re.findall(r"\d+", stage_label or "")]
    if not digits:
        return 0, None
    if len(digits) == 1:
        return digits[0], digits[0]
    return digits[0], digits[1]

def _resolve_crop_stage(days_since_sowing: int) -> str:
    tree = _load_maize_tree()
    stage_labels = list(tree.get("metadata", {}).get("stages", []))
    if not stage_labels:
        raise ValueError("No crop stages configured in maize knowledge tree metadata")

    parsed = sorted(
        (
            _parse_stage_label(label)[0],
            _parse_stage_label(label)[1],
            label,
        )
        for label in stage_labels
    )

    # Exact "0 Days" should mean sowing day only, not the whole 0-14 day window.
    for start_day, end_day, label in parsed:
        if start_day == 0 and end_day == 0 and days_since_sowing == 0:
            return label
        if start_day == end_day and start_day > 0 and days_since_sowing <= end_day:
            return label
        if end_day is not None and start_day != end_day and start_day <= days_since_sowing <= end_day:
            return label

    resolved = parsed[0][2]
    for start_day, _, label in parsed:
        if days_since_sowing >= start_day:
            resolved = label
        else:
            break
    return resolved

def execute_set_crop_stage(sowing_date: str) -> Dict[str, Any]:
    """Resolve the current maize crop stage from a normalized sowing date."""
    try:
        sowing = datetime.strptime(sowing_date, "%Y-%m-%d").date()
    except ValueError:
        return {"error": "Invalid sowing_date format. Expected YYYY-MM-DD."}

    today = datetime.now().date()
    days_since_sowing = (today - sowing).days
    if days_since_sowing < 0:
        return {
            "error": "Sowing date is in the future.",
            "sowing_date": sowing_date,
            "current_date": today.isoformat(),
        }

    crop_stage = _resolve_crop_stage(days_since_sowing)
    return {
        "sowing_date": sowing_date,
        "current_date": today.isoformat(),
        "days_since_sowing": days_since_sowing,
        "crop_stage": crop_stage,
        "source": "maize_knowledge_tree.metadata.stages",
    }

def _iter_stage_entries(crop_stage: str | None) -> List[Tuple[str, str, Dict[str, Any]]]:
    tree = _load_maize_tree()
    entries: List[Tuple[str, str, Dict[str, Any]]] = []
    knowledge_tree = tree.get("knowledge_tree", {})
    stages = [crop_stage] if crop_stage else list(knowledge_tree.keys())
    for stage_name in stages:
        stage_tree = knowledge_tree.get(stage_name) or {}
        for subtopic in stage_tree.get("subtopics", []):
            for entry in subtopic.get("entries", []):
                entries.append((stage_name, subtopic.get("subtopic"), entry))
    return entries

def _direct_lookup(crop_stage: str | None, query: str, english_query: str | None = None) -> Dict[str, Any] | None:
    normalized_candidates = [_normalize_question(query)]
    if english_query:
        normalized_candidates.append(_normalize_question(english_query))

    for stage_name, subtopic_name, entry in _iter_stage_entries(crop_stage):
        normalized_question = _normalize_question(entry.get("question", ""))
        if normalized_question in normalized_candidates:
            return {
                "lookup_mode": "direct_lookup",
                "crop_stage": stage_name,
                "subtopic": subtopic_name,
                "question": entry.get("question"),
                "category": entry.get("category"),
                "recommendation": entry.get("recommendation"),
            }
    return None

def _keyword_augmented_query(query: str, key: str) -> str:
    base = (query or "").strip()
    hints = ", ".join(_DOMAIN_HINTS.get(key, []))
    if not base:
        return hints
    return f"{base}. Focus on: {hints}."

def _normalize_sub_queries(candidate: dict, original_query: str) -> dict:
    normalized: dict[str, str] = {}
    for key in _COLLECTION_MAP:
        proposed = candidate.get(key)
        if isinstance(proposed, str) and proposed.strip():
            normalized[key] = proposed.strip()
        else:
            normalized[key] = _keyword_augmented_query(original_query, key)
    return normalized

def generate_sub_queries(
    query: str,
    chat_history: list | None = None,
    conversation_id: str | None = None,
    user_id: str | None = None,
) -> dict:
    """Ask the LLM to generate targeted sub-queries for each Qdrant collection."""
    from pipeline.llm_factory import get_llm
    from langchain_core.messages import SystemMessage, HumanMessage

    try:
        llm = get_llm()
        context_str = ""
        if chat_history:
            context_str = "Recent Chat History:\n" + "\n".join(
                [f"{m.get('role', 'user')}: {m.get('content', '')}" for m in chat_history]
            ) + "\n\n"

        messages = [
            SystemMessage(content=_SUB_QUERY_SYSTEM),
            HumanMessage(content=f"{context_str}Current Query to expand: {query}"),
        ]

        msg = llm.invoke(messages)
        log_llm_call(
            conversation_id=conversation_id,
            user_id=user_id,
            source="tool.generate_sub_queries",
            request={"query": query, "chat_history_count": len(chat_history or [])},
            response={"has_content": bool(getattr(msg, "content", ""))},
        )

        content = msg.content
        if "```json" in content:
            content = content.split("```json")[1].split("```")[0].strip()
        elif "```" in content:
            content = content.split("```")[1].strip()

        parsed = json.loads(content)
        if not isinstance(parsed, dict):
            raise ValueError("Sub-query generator did not return a JSON object")
        return _normalize_sub_queries(parsed, query)

    except Exception as exc:
        log_llm_call(
            conversation_id=conversation_id,
            user_id=user_id,
            source="tool.generate_sub_queries.error",
            request={"query": query, "chat_history_count": len(chat_history or [])},
            error=str(exc),
        )
        # Fallback: use original query for all collections
        return {
            key: _keyword_augmented_query(query, key)
            for key in _COLLECTION_MAP
        }

def _extract_hits(result: Any) -> List[Any]:
    """Handle qdrant-client response shape differences across versions."""
    if result is None:
        return []
    if isinstance(result, list):
        return result

    points = getattr(result, "points", None)
    if isinstance(points, list):
        return points

    inner_result = getattr(result, "result", None)
    if isinstance(inner_result, list):
        return inner_result

    inner_points = getattr(inner_result, "points", None)
    if isinstance(inner_points, list):
        return inner_points

    return []

def _json_safe(value: Any) -> Any:
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    if isinstance(value, dict):
        return {str(k): _json_safe(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_json_safe(v) for v in value]
    if isinstance(value, tuple):
        return [_json_safe(v) for v in value]
    return str(value)

def _search_collection(
    qdrant_client,
    *,
    collection_name: str,
    sub_query: str,
    query_vector: List[float],
    top_k: int,
) -> Dict[str, Any]:
    """Execute a single collection search and normalize the hits."""
    start = time.perf_counter()
    chunks: List[Dict[str, Any]] = []
    response = qdrant_client.query_points(
        collection_name=collection_name,
        query=query_vector,
        limit=top_k,
    )
    for hit in _extract_hits(response):
        payload = getattr(hit, "payload", None) or {}
        chunks.append(
            {
                "collection": collection_name,
                "sub_query": sub_query,
                "score": round(float(hit.score), 4),
                "content": payload.get("page_content", ""),
                "metadata": payload.get("metadata", {}),
            }
        )
    return {
        "chunks": chunks,
        "elapsed_ms": round((time.perf_counter() - start) * 1000.0, 2),
    }

def execute_geocode_location(address: str) -> Dict[str, Any]:
    """Resolve an address to latitude and longitude using Geopy/Nominatim."""
    from geopy.geocoders import Nominatim
    try:
        geolocator = Nominatim(user_agent="agritech_ai_assistant")
        location = geolocator.geocode(address)
        if location:
            raw_address = getattr(location, "raw", {}).get("address", {})
            locality = (
                raw_address.get("city")
                or raw_address.get("town")
                or raw_address.get("village")
                or raw_address.get("hamlet")
                or raw_address.get("county")
                or address
            )
            return {
                "address":          address,
                "resolved_address": location.address,
                "location":         locality,
                "state":            raw_address.get("state"),
                "country":          raw_address.get("country"),
                "latitude":         location.latitude,
                "longitude":        location.longitude,
            }
        return {
            "error": (
                f"Could not resolve the address: '{address}'. "
                "Please ask the user for a more specific city or village name."
            )
        }
    except Exception as e:
        return {"error": str(e)}

def execute_get_weather(
    latitude: float = None,
    longitude: float = None,
) -> Dict[str, Any]:
    """Fetch current weather and 3-day forecast from Open-Meteo."""
    try:
        if latitude is None or longitude is None:
            return {
                "error": (
                    "Missing coordinates. Ask the user for their address first, "
                    "resolve it with geocode_location, and then call get_weather."
                )
            }

        url = (
            f"https://api.open-meteo.com/v1/forecast"
            f"?latitude={latitude}&longitude={longitude}"
            f"&current_weather=true"
            f"&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,"
            f"relative_humidity_2m_max&timezone=auto"
        )
        r = requests.get(url, timeout=10)
        r.raise_for_status()

        data  = r.json()
        cw    = data.get("current_weather", {})
        daily = data.get("daily", {})

        forecast = []
        times = daily.get("time", [])
        for i in range(1, 4):
            if i < len(times):
                forecast.append({
                    "date":     times[i],
                    "temp_max": daily.get("temperature_2m_max",       [None] * 5)[i],
                    "temp_min": daily.get("temperature_2m_min",       [None] * 5)[i],
                    "rain_mm":  daily.get("precipitation_sum",        [0]    * 5)[i],
                    "humidity": daily.get("relative_humidity_2m_max", [None] * 5)[i],
                })

        return {
            "current": {
                "temperature":  cw.get("temperature"),
                "wind_speed":   cw.get("windspeed"),
                "weather_code": cw.get("weathercode"),
            },
            "forecast_3day": forecast,
        }
    except Exception as e:
        return {"error": str(e)}

def _dedupe(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    seen: set = set()
    out: List[Dict[str, Any]] = []
    for row in rows:
        key = (row.get("url") or "", row.get("title") or "")
        if key in seen:
            continue
        seen.add(key)
        out.append(row)
    return out

def _from_duckduckgo() -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    today    = datetime.now(timezone.utc)
    week_ago = today - timedelta(days=7)
    date_hint       = f"after:{week_ago.strftime('%Y-%m-%d')}"
    time_scoped_q   = f"{scoped_query} {date_hint}"

    r = requests.get(
        "https://api.duckduckgo.com/",
        params={"q": time_scoped_q, "format": "json", "no_redirect": 1, "no_html": 1},
        headers=_HEADERS,
        timeout=8,
    )
    r.raise_for_status()
    data = r.json()

    abstract = (data.get("AbstractText") or "").strip()
    if abstract:
        rows.append({
            "title":   data.get("Heading", "Result"),
            "snippet": abstract,
            "url":     data.get("AbstractURL", ""),
            "source":  "duckduckgo_instant",
        })

    for item in data.get("RelatedTopics") or []:
        if len(rows) >= max_results:
            break
        if isinstance(item, dict) and "Text" in item:
            rows.append({
                "title":   "Related",
                "snippet": item.get("Text", ""),
                "url":     item.get("FirstURL", ""),
                "source":  "duckduckgo_instant",
            })
    return rows

def _extract_hits(result: Any) -> list[Any]:
    if result is None:
        return []
    if isinstance(result, list):
        return result

    points = getattr(result, "points", None)
    if isinstance(points, list):
        return points

    inner_result = getattr(result, "result", None)
    if isinstance(inner_result, list):
        return inner_result

    inner_points = getattr(inner_result, "points", None)
    if isinstance(inner_points, list):
        return inner_points

    return []

